<script setup lang="ts">
import { ref,computed,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useApp } from '../stores/app'
import { categories } from '../lib/types'
import type { Post,Category } from '../lib/types'
import { secureUrl } from '../lib/format'
import Icon from '../components/Icon.vue'
const app=useApp(),route=useRoute(),router=useRouter(),existing=app.posts.find(p=>p.id===route.params.id)
const title=ref(existing?.title||''),category=ref<Category>(existing?.category||'科技'),short=ref(existing?.short_summary||''),medium=ref(existing?.medium_summary||''),content=ref(existing?.full_content||''),tags=ref(existing?.tags.join('，')||''),source=ref(existing?.source_url||''),sourceName=ref(existing?.source_name||''),points=ref(existing?.key_points.join('\n')||''),attribution=ref(existing?.image_attribution||''),image=ref<File|null>(null),preview=ref(existing?.image_url||''),ai=ref(existing?.is_ai_generated_image||false),busy=ref(false),error=ref('')
const date=ref(new Date(new Date(existing?.source_published_at||Date.now()).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16))
let objectUrl=''
async function pick(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){error.value='请选择 8MB 内的 JPG、PNG、WebP';return}image.value=file;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);preview.value=objectUrl}
onBeforeUnmount(()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)})
const canPublish=computed(()=>title.value.trim().length>=4&&short.value.trim().length>=20&&content.value.trim().length>=50)
async function save(status:'draft'|'published'){busy.value=true;error.value='';try{if(source.value&&!secureUrl(source.value))throw new Error('原文链接必须是 HTTPS 地址');if((image.value||existing?.image_path)&&!attribution.value.trim())throw new Error('请补充配图的来源与许可说明');const imagePath=image.value?await app.uploadImage(image.value):existing?.image_path||null;const post:Post={content_kind:existing?.content_kind||'news',id:existing?.id||crypto.randomUUID(),title:title.value.trim(),category:category.value,short_summary:short.value.trim(),medium_summary:medium.value.trim(),full_content:content.value.trim(),key_points:points.value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,5),tags:tags.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean).slice(0,10),source_name:sourceName.value.trim()||'我的私人手记',source_url:source.value.trim(),source_published_at:new Date(date.value).toISOString(),event_time:existing?.event_time||null,generated_at:existing?.generated_at||new Date().toISOString(),published_at:status==='published'?existing?.published_at||new Date().toISOString():null,image_path:app.demo?null:imagePath,image_url:app.demo?imagePath||preview.value:undefined,image_attribution:attribution.value.trim(),is_ai_generated_image:ai.value,status,verification_status:existing?.verification_status||'pending',pinned:existing?.pinned||false,origin:existing?.origin==='agent'?'agent':'manual'};if(post.origin==='agent'&&status==='published'&&post.verification_status!=='verified')throw new Error('Agent 内容需先在后台核验，才可以发布');await app.savePost(post);const saved=app.posts.find(p=>p.id===post.id);await router.push(saved?.status==='published'?`/post/${post.id}`:'/admin')}catch(e){error.value=app.errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="page editor-page"><div class="page-heading"><div><div class="eyebrow">A THOUGHT WORTH KEEPING</div><h1>{{existing?'编辑这条发现。':'记录一个，值得的发现。'}}</h1><p>这是你的私人编辑台。手动内容会明确标记为所有者手记。</p></div><button class="btn outline small" @click="router.back()"><Icon name="ArrowLeft" :size="16"/>返回</button></div><form class="editor-layout" @submit.prevent="save('published')"><section class="form-card"><label>标题 <span>*</span><input v-model="title" required minlength="4" maxlength="180" placeholder="一个清晰、有信息量的标题"/></label><div class="form-row"><label>分类<select v-model="category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>标签<input v-model="tags" maxlength="200" placeholder="AI，世界模型，阅读笔记"/></label></div><label>15 秒速读 <span>*</span><textarea v-model="short" required minlength="20" maxlength="500" rows="3" placeholder="用自己的话，说清楚核心内容（至少 20 字）"></textarea></label><label>1 分钟了解<textarea v-model="medium" maxlength="1500" rows="4" placeholder="补充背景、核心进展和为什么值得关注"></textarea></label><label>完整解读 / 私人图文 <span>*</span><textarea v-model="content" required minlength="50" maxlength="15000" rows="10" placeholder="写下完整内容（至少 50 字），段落之间留一个空行…"></textarea></label><label>关键信息<textarea v-model="points" maxlength="1500" rows="3" placeholder="每行一条，最多 5 条"></textarea></label></section><aside class="editor-aside"><section class="form-card"><h3>封面与来源</h3><label class="upload-cover"><img v-if="preview" :src="preview" alt="封面预览"/><template v-else><Icon name="ImagePlus" :size="28"/><strong>添加你的配图</strong><small>JPG / PNG / WebP · 最大 8MB</small></template><input type="file" accept="image/jpeg,image/png,image/webp" @change="pick"/></label><label>图片来源与许可<input v-model="attribution" maxlength="500" placeholder="例如：本人拍摄 / CC BY 4.0 + 作者"/></label><label class="checkbox-label"><input v-model="ai" type="checkbox"/>这是 AI 生成示意图</label><label>原始来源名称<input v-model="sourceName" maxlength="120" placeholder="留空则标为我的私人手记"/></label><label>原文链接<input v-model="source" type="url" maxlength="2000" placeholder="https://…"/></label><label>原文发布 / 手记时间<input v-model="date" type="datetime-local" required/></label></section><div class="editor-save"><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary" :disabled="busy||!canPublish"><Icon name="Send" :size="16"/>{{busy?'正在保存…':'发布到私人首页'}}</button><button type="button" class="btn outline" :disabled="busy||!title.trim()" @click="save('draft')"><Icon name="FileText" :size="16"/>保存草稿</button><small><Icon name="LockKeyhole" :size="12"/>{{app.demo?'演示内容保存在此浏览器':'仅所有者可见，私人存储'}}</small></div></aside></form></div></template>
